func  (this *krakenfutures) ParseBalance(response interface{}) interface{}  {
    //
    // cashAccount
    //
    //    {
    //        "balances": {
    //            "eur": "0.0",
    //            "gbp": "0.0",
    //            "bch": "0.0",
    //            "xrp": "2.20188538338",
    //            "usd": "0.0",
    //            "eth": "0.0",
    //            "usdt": "0.0",
    //            "ltc": "0.0",
    //            "usdc": "0.0",
    //            "xbt": "0.0"
    //        },
    //        "type": "cashAccount"
    //    }
    //
    // marginAccount e,g, fi_xrpusd
    //
    //    {
    //        "auxiliary": {
    //            "usd": "0",
    //            "pv": "11.0",
    //            "pnl": "0.0",
    //            "af": "11.0",
    //            "funding": "0.0"
    //        },
    //        "marginRequirements": { im: '0.0', mm: '0.0', lt: '0.0', tt: "0.0" },
    //        "triggerEstimates": { im: '0', mm: '0', lt: "0", tt: "0" },
    //        "balances": { xrp: "11.0" },
    //        "currency": "xrp",
    //        "type": "marginAccount"
    //    }
    //
    // flex/multiCollateralMarginAccount
    //
    //    {
    //       "currencies": {
    //            "USDT": {
    //                "quantity": "1",
    //                "value": "1.0001",
    //                "collateral": "0.9477197625",
    //                "available": "1.0"
    //             }
    //       },
    //       "initialMargin": "0.0",
    //       "initialMarginWithOrders": "0.0",
    //       "maintenanceMargin": "0.0",
    //       "balanceValue": "1.0",
    //       "portfolioValue": "1.0",
    //       "collateralValue": "0.95",
    //       "pnl": "0.0",
    //       "unrealizedFunding": "0.0",
    //       "totalUnrealized": "0.0",
    //       "totalUnrealizedAsMargin": "0.0",
    //       "availableMargin": "0.95",
    //       "marginEquity": "0.95",
    //       "type": "multiCollateralMarginAccount"
    //    }
    //
    var accountType interface{} = this.SafeString2(response, "accountType", "type")
    var isFlex interface{} =     (ccxt.IsEqual(accountType, "multiCollateralMarginAccount"))
    var isCash interface{} =     (ccxt.IsEqual(accountType, "cashAccount"))
    var balances interface{} = this.SafeValue2(response, "balances", "currencies", map[string]interface{} {})
    var result interface{} = map[string]interface{} {}
    var currencyIds interface{} = ccxt.ObjectKeys(balances)
    for i := 0; ccxt.IsLessThan(i, ccxt.GetArrayLength(currencyIds)); i++ {
        var currencyId interface{} = ccxt.GetValue(currencyIds, i)
        var balance interface{} = ccxt.GetValue(balances, currencyId)
        var code interface{} = this.SafeCurrencyCode(currencyId)
        var splitCode interface{} = ccxt.Split(code, "_")
        var codeLength interface{} =         ccxt.GetArrayLength(splitCode)
        if ccxt.IsTrue(ccxt.IsGreaterThan(codeLength, 1)) {
            continue
        }
        var account interface{} = this.Account()
        if ccxt.IsTrue(isFlex) {
            ccxt.AddElementToObject(account, "total", this.SafeString(balance, "quantity"))
            ccxt.AddElementToObject(account, "free", this.SafeString(balance, "available"))
        } else if ccxt.IsTrue(isCash) {
            ccxt.AddElementToObject(account, "used", "0.0")
            ccxt.AddElementToObject(account, "total", balance)
        } else {
            var auxiliary interface{} = this.SafeValue(response, "auxiliary")
            ccxt.AddElementToObject(account, "free", this.SafeString(auxiliary, "af"))
            ccxt.AddElementToObject(account, "total", this.SafeString(auxiliary, "pv"))
        }
        ccxt.AddElementToObject(result, code, account)
    }
    return this.SafeBalance(result)
}
/**
 * @method
 * @name krakenfutures#fetchFundingRates
 * @description fetch the current funding rates for multiple markets
 * @see https://docs.futures.kraken.com/#http-api-trading-v3-api-market-data-get-tickers
 * @param {string[]} symbols unified market symbols
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {ccxt.Order[]} an array of [funding rate structures]{@link https://docs.ccxt.com/#/?id=funding-rate-structure}
 */
func  (this *krakenfutures) FetchFundingRates(optionalArgs ...interface{}) <- chan interface{} {
            ch := make(chan interface{})
            go func() interface{} {
                defer close(ch)
                defer ccxt.ReturnPanicError(ch)
                    symbols := ccxt.GetArg(optionalArgs, 0, nil)
            _ = symbols
            params := ccxt.GetArg(optionalArgs, 1, map[string]interface{} {})
            _ = params
        
            retRes22698 := (<-this.LoadMarkets())
            ccxt.PanicOnError(retRes22698)
            var marketIds interface{} = this.MarketIds(symbols)
        
            response:= (<-this.PublicGetTickers(params))
            ccxt.PanicOnError(response)
            var tickers interface{} = this.SafeList(response, "tickers", []interface{}{})
            var fundingRates interface{} = []interface{}{}
            for i := 0; ccxt.IsLessThan(i, ccxt.GetArrayLength(tickers)); i++ {
                var entry interface{} = ccxt.GetValue(tickers, i)
                var entry_symbol interface{} = this.SafeValue(entry, "symbol")
                if ccxt.IsTrue(!ccxt.IsEqual(marketIds, nil)) {
                    if !ccxt.IsTrue(this.InArray(entry_symbol, marketIds)) {
                        continue
                    }
                }
                var market interface{} = this.SafeMarket(entry_symbol)
                var parsed interface{} = this.ParseFundingRate(entry, market)
                ccxt.AppendToArray(&fundingRates, parsed)
            }
        
            ch <- this.IndexBy(fundingRates, "symbol")
            return nil
        
            }()
            return ch
        }
func  (this *krakenfutures) ParseFundingRate(ticker interface{}, optionalArgs ...interface{}) interface{}  {
    //
    // {"ask": 26.283,
    //  "askSize": 4.6,
    //  "bid": 26.201,
    //  "bidSize": 190,
    //  "fundingRate": -0.000944642727438883,
    //  "fundingRatePrediction": -0.000872671532340275,
    //  "indexPrice": 26.253,
    //  "last": 26.3,
    //  "lastSize": 0.1,
    //  "lastTime": "2023-06-11T18:55:28.958Z",
    //  "markPrice": 26.239,
    //  "open24h": 26.3,
    //  "openInterest": 641.1,
    //  "pair": "COMP:USD",
    //  "postOnly": False,
    //  "suspended": False,
    //  "symbol": "pf_compusd",
    //  "tag": "perpetual",
    //  "vol24h": 0.1,
    //  "volumeQuote": 2.63}
    //
    market := ccxt.GetArg(optionalArgs, 0, nil)
    _ = market
    var fundingRateMultiplier interface{} = "8" // https://support.kraken.com/hc/en-us/articles/9618146737172-Perpetual-Contracts-Funding-Rate-Method-Prior-to-September-29-2022
    var marketId interface{} = this.SafeString(ticker, "symbol")
    var symbol interface{} = this.Symbol(marketId)
    var timestamp interface{} = this.Parse8601(this.SafeString(ticker, "lastTime"))
    var indexPrice interface{} = this.SafeNumber(ticker, "indexPrice")
    var markPriceString interface{} = this.SafeString(ticker, "markPrice")
    var markPrice interface{} = this.ParseNumber(markPriceString)
    var fundingRateString interface{} = this.SafeString(ticker, "fundingRate")
    var fundingRateResult interface{} = ccxt.Precise.StringDiv(ccxt.Precise.StringMul(fundingRateString, fundingRateMultiplier), markPriceString)
    var fundingRate interface{} = this.ParseNumber(fundingRateResult)
    var nextFundingRateString interface{} = this.SafeString(ticker, "fundingRatePrediction")
    var nextFundingRateResult interface{} = ccxt.Precise.StringDiv(ccxt.Precise.StringMul(nextFundingRateString, fundingRateMultiplier), markPriceString)
    var nextFundingRate interface{} = this.ParseNumber(nextFundingRateResult)
    return map[string]interface{} {
        "info": ticker,
        "symbol": symbol,
        "markPrice": markPrice,
        "indexPrice": indexPrice,
        "interestRate": nil,
        "estimatedSettlePrice": nil,
        "timestamp": timestamp,
        "datetime": this.Iso8601(timestamp),
        "fundingRate": fundingRate,
        "fundingTimestamp": nil,
        "fundingDatetime": nil,
        "nextFundingRate": nextFundingRate,
        "nextFundingTimestamp": nil,
        "nextFundingDatetime": nil,
        "previousFundingRate": nil,
        "previousFundingTimestamp": nil,
        "previousFundingDatetime": nil,
        "interval": nil,
    }
}
