func  (this *krakenfutures) ParseAccount(account interface{}) interface{}  {
    var accountByType interface{} = map[string]interface{} {
        "main": "cash",
        "funding": "cash",
        "future": "cash",
        "futures": "cash",
        "cashAccount": "cash",
        "multiCollateralMarginAccount": "flex",
        "multiCollateral": "flex",
        "multiCollateralMargin": "flex",
    }
    if ccxt.IsTrue(ccxt.InOp(accountByType, account)) {
        return ccxt.GetValue(accountByType, account)
    } else if ccxt.IsTrue(ccxt.InOp(this.Markets, account)) {
        var market interface{} = this.Market(account)
        var marketId interface{} = ccxt.GetValue(market, "id")
        var splitId interface{} = ccxt.Split(marketId, "_")
        if ccxt.IsTrue(ccxt.GetValue(market, "inverse")) {
            return ccxt.Add("fi_", this.SafeString(splitId, 1))
        } else {
            return ccxt.Add("fv_", this.SafeString(splitId, 1))
        }
    } else {
        return account
    }
}
